495		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
496		// Prefer attaching this tree to the latest session in v2.
497		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
498			if len(summary.Sessions) > 0 {
