			return false, fmt.Errorf("failed to write missing v2 session %d: %w", sessionIdx, writeErr)
		}
		repaired = true
	}

	// Phase 3: Restore task metadata for any task sessions (idempotent via MergeKeepExisting).
	if hasTaskSessions {
