func repairPartialV2Checkpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary) (bool, error) {
	repaired := false

	// Load v1 summary once for reconciliation and task metadata repair.
	v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
	if err != nil {
		return false, fmt.Errorf("failed to read v1 summary: %w", err)
	}
	if v1Summary == nil {
		return false, nil
	}

	existingSessionCount := len(v2Summary.Sessions)
	hasTaskSessions := false

	// Phase 1: Repair existing sessions with missing /full artifacts.
	for sessionIdx := range existingSessionCount {
		ok, checkErr := hasFullSessionArtifacts(repo, v2Store, info.CheckpointID, sessionIdx)
		if checkErr != nil {
			return false, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
		}
		if ok {
			continue
		}

		content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
		if readErr != nil {
			return false, fmt.Errorf("failed to read v1 session %d while repairing v2: %w", sessionIdx, readErr)
		}
		if content.Metadata.IsTask {
			hasTaskSessions = true
		}

		updateOpts := checkpoint.UpdateCommittedOptions{
			CheckpointID: info.CheckpointID,
			SessionID:    content.Metadata.SessionID,
			Transcript:   content.Transcript,
			Prompts:      checkpoint.SplitPromptContent(content.Prompts),
			Agent:        content.Metadata.Agent,
		}
		if compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata); compacted != nil {
			updateOpts.CompactTranscript = compacted
		}

		if updateErr := v2Store.UpdateCommitted(ctx, updateOpts); updateErr != nil {
			return false, fmt.Errorf("failed to repair v2 session %d: %w", sessionIdx, updateErr)
		}
		repaired = true
	}

	// Phase 2: Append any v1 sessions that were never written to v2.
	for sessionIdx := existingSessionCount; sessionIdx < len(v1Summary.Sessions); sessionIdx++ {
		content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
		if readErr != nil {
			return false, fmt.Errorf("failed to read v1 session %d for reconciliation: %w", sessionIdx, readErr)
		}
		if content.Metadata.IsTask {
			hasTaskSessions = true
		}

		opts := buildMigrateWriteOpts(content, info)
		if compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata); compacted != nil {
			opts.CompactTranscript = compacted
		}

		if writeErr := v2Store.WriteCommitted(ctx, opts); writeErr != nil {
			return false, fmt.Errorf("failed to write missing v2 session %d: %w", sessionIdx, writeErr)
		}
		repaired = true
	}

	// Phase 3: Restore task metadata for any task sessions (idempotent via MergeKeepExisting).
	if hasTaskSessions {
		if taskErr := copyTaskMetadataToV2(repo, v1Store, v2Store, info.CheckpointID, v1Summary); taskErr != nil {
			logging.Warn(ctx, "failed to copy task metadata during repair",
				slog.String("checkpoint_id", string(info.CheckpointID)),
				slog.String("error", taskErr.Error()),
			)
		}
	}

	return repaired, nil
}

func hasFullSessionArtifacts(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int) (bool, error) {
	// Check /full/current first.
	if ok, err := hasSessionArtifactsInRef(repo, v2Store, paths.V2FullCurrentRefName, cpID, sessionIdx); err != nil {
		return false, err
	} else if ok {
		return true, nil
	}

	// Check archived /full/* generations.
	archived, err := v2Store.ListArchivedGenerations()
	if err != nil {
		return false, nil //nolint:nilerr // Best-effort: listing failure shouldn't block repair.
	}
	for i := len(archived) - 1; i >= 0; i-- {
		refName := paths.V2FullRefPrefix + archived[i]
		ok, archiveErr := hasSessionArtifactsInRef(repo, v2Store, refName, cpID, sessionIdx)
		if archiveErr != nil {
			continue // Best-effort: skip unreadable archived generations.
		}
		if ok {
			return true, nil
		}
	}

	return false, nil
}

func hasSessionArtifactsInRef(repo *git.Repository, v2Store *checkpoint.V2GitStore, refName string, cpID id.CheckpointID, sessionIdx int) (bool, error) {
	_, rootTreeHash, err := v2Store.GetRefState(plumbing.ReferenceName(refName))
	if err != nil {
		return false, nil //nolint:nilerr // Missing ref means artifacts are absent.
	}

	rootTree, err := repo.TreeObject(rootTreeHash)
	if err != nil {
		return false, fmt.Errorf("failed to read tree for %s: %w", refName, err)
	}

	sessionPath := fmt.Sprintf("%s/%d", cpID.Path(), sessionIdx)
	sessionTree, err := rootTree.Tree(sessionPath)
	if err != nil {
		return false, nil //nolint:nilerr // Missing session path means artifacts are absent.
	}

	hasTranscript := false
	for _, entry := range sessionTree.Entries {
		if entry.Name == paths.TranscriptFileName || strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
			hasTranscript = true
			break
		}
	}
	if !hasTranscript {
		return false, nil
	}

	if _, err := sessionTree.File(paths.ContentHashFileName); err != nil {
		return false, nil //nolint:nilerr // Missing content hash indicates incomplete artifacts.
	}

	return true, nil
}

